-- Supplemental constraints translated from the PostgreSQL backup.
-- Apply after 0001_public_schema.sql and before importing snapshot data.

CREATE UNIQUE INDEX IF NOT EXISTS "businesses_business_code_key" ON "businesses" ("business_code");
CREATE UNIQUE INDEX IF NOT EXISTS "device_registration_keys_key_hash_key" ON "device_registration_keys" ("key_hash");
CREATE UNIQUE INDEX IF NOT EXISTS "invoices_order_id_key" ON "invoices" ("order_id");
CREATE UNIQUE INDEX IF NOT EXISTS "kot_device_print_jobs_business_id_order_id_ticket_number_key" ON "kot_device_print_jobs" ("business_id", "order_id", "ticket_number");
CREATE UNIQUE INDEX IF NOT EXISTS "loyalty_transactions_reference_type_reference_id_transactio_key" ON "loyalty_transactions" ("reference_type", "reference_id", "transaction_type");
CREATE UNIQUE INDEX IF NOT EXISTS "orders_order_number_key" ON "orders" ("order_number");
CREATE UNIQUE INDEX IF NOT EXISTS "public_menu_push_subscriptions_business_id_endpoint_key" ON "public_menu_push_subscriptions" ("business_id", "endpoint");
CREATE UNIQUE INDEX IF NOT EXISTS "public_menu_settings_token_key" ON "public_menu_settings" ("token");
CREATE UNIQUE INDEX IF NOT EXISTS "qr_guest_sessions_session_token_hash_key" ON "qr_guest_sessions" ("session_token_hash");
CREATE UNIQUE INDEX IF NOT EXISTS "registered_devices_device_id_key" ON "registered_devices" ("device_id");
CREATE UNIQUE INDEX IF NOT EXISTS "support_users_username_key" ON "support_users" ("username");
CREATE UNIQUE INDEX IF NOT EXISTS "users_username_key" ON "users" ("username");
CREATE TRIGGER IF NOT EXISTS "d1_check_billing_adjustments_calculation_check_insert" BEFORE INSERT ON "billing_adjustments" WHEN NOT (NEW."calculation" IN ('percent', 'fixed')) BEGIN SELECT RAISE(ABORT, 'constraint failed: billing_adjustments_calculation_check'); END;
CREATE TRIGGER IF NOT EXISTS "d1_check_billing_adjustments_calculation_check_update" BEFORE UPDATE ON "billing_adjustments" WHEN NOT (NEW."calculation" IN ('percent', 'fixed')) BEGIN SELECT RAISE(ABORT, 'constraint failed: billing_adjustments_calculation_check'); END;
CREATE TRIGGER IF NOT EXISTS "d1_check_billing_adjustments_kind_check_insert" BEFORE INSERT ON "billing_adjustments" WHEN NOT (NEW."kind" IN ('discount', 'charge')) BEGIN SELECT RAISE(ABORT, 'constraint failed: billing_adjustments_kind_check'); END;
CREATE TRIGGER IF NOT EXISTS "d1_check_billing_adjustments_kind_check_update" BEFORE UPDATE ON "billing_adjustments" WHEN NOT (NEW."kind" IN ('discount', 'charge')) BEGIN SELECT RAISE(ABORT, 'constraint failed: billing_adjustments_kind_check'); END;
CREATE TRIGGER IF NOT EXISTS "d1_check_billing_adjustments_value_check_insert" BEFORE INSERT ON "billing_adjustments" WHEN NOT (NEW."value" >= 0) BEGIN SELECT RAISE(ABORT, 'constraint failed: billing_adjustments_value_check'); END;
CREATE TRIGGER IF NOT EXISTS "d1_check_billing_adjustments_value_check_update" BEFORE UPDATE ON "billing_adjustments" WHEN NOT (NEW."value" >= 0) BEGIN SELECT RAISE(ABORT, 'constraint failed: billing_adjustments_value_check'); END;
CREATE TRIGGER IF NOT EXISTS "d1_check_business_licenses_valid_term_insert" BEFORE INSERT ON "business_licenses" WHEN NOT (((NEW."license_type" = 'Trial' AND NEW."duration_months" = 1) OR (NEW."license_type" = 'Sales' AND NEW."duration_months" IN (3, 6, 12)))) BEGIN SELECT RAISE(ABORT, 'constraint failed: business_licenses_valid_term'); END;
CREATE TRIGGER IF NOT EXISTS "d1_check_business_licenses_valid_term_update" BEFORE UPDATE ON "business_licenses" WHEN NOT (((NEW."license_type" = 'Trial' AND NEW."duration_months" = 1) OR (NEW."license_type" = 'Sales' AND NEW."duration_months" IN (3, 6, 12)))) BEGIN SELECT RAISE(ABORT, 'constraint failed: business_licenses_valid_term'); END;
CREATE TRIGGER IF NOT EXISTS "d1_check_business_sequence_counters_next_number_check_insert" BEFORE INSERT ON "business_sequence_counters" WHEN NOT (NEW."next_number" > 0) BEGIN SELECT RAISE(ABORT, 'constraint failed: business_sequence_counters_next_number_check'); END;
CREATE TRIGGER IF NOT EXISTS "d1_check_business_sequence_counters_next_number_check_update" BEFORE UPDATE ON "business_sequence_counters" WHEN NOT (NEW."next_number" > 0) BEGIN SELECT RAISE(ABORT, 'constraint failed: business_sequence_counters_next_number_check'); END;
CREATE TRIGGER IF NOT EXISTS "d1_check_expenses_amount_check_insert" BEFORE INSERT ON "expenses" WHEN NOT (NEW."amount" >= 0) BEGIN SELECT RAISE(ABORT, 'constraint failed: expenses_amount_check'); END;
CREATE TRIGGER IF NOT EXISTS "d1_check_expenses_amount_check_update" BEFORE UPDATE ON "expenses" WHEN NOT (NEW."amount" >= 0) BEGIN SELECT RAISE(ABORT, 'constraint failed: expenses_amount_check'); END;
CREATE TRIGGER IF NOT EXISTS "d1_check_invoice_number_counters_next_number_check_insert" BEFORE INSERT ON "invoice_number_counters" WHEN NOT (NEW."next_number" > 0) BEGIN SELECT RAISE(ABORT, 'constraint failed: invoice_number_counters_next_number_check'); END;
CREATE TRIGGER IF NOT EXISTS "d1_check_invoice_number_counters_next_number_check_update" BEFORE UPDATE ON "invoice_number_counters" WHEN NOT (NEW."next_number" > 0) BEGIN SELECT RAISE(ABORT, 'constraint failed: invoice_number_counters_next_number_check'); END;
CREATE TRIGGER IF NOT EXISTS "d1_check_qr_guest_otp_challenges_attempts_check_insert" BEFORE INSERT ON "qr_guest_otp_challenges" WHEN NOT (NEW."attempts" >= 0 AND NEW."attempts" <= 5) BEGIN SELECT RAISE(ABORT, 'constraint failed: qr_guest_otp_challenges_attempts_check'); END;
CREATE TRIGGER IF NOT EXISTS "d1_check_qr_guest_otp_challenges_attempts_check_update" BEFORE UPDATE ON "qr_guest_otp_challenges" WHEN NOT (NEW."attempts" >= 0 AND NEW."attempts" <= 5) BEGIN SELECT RAISE(ABORT, 'constraint failed: qr_guest_otp_challenges_attempts_check'); END;
CREATE TRIGGER IF NOT EXISTS "d1_check_qr_guest_otp_challenges_menu_token_hash_check_insert" BEFORE INSERT ON "qr_guest_otp_challenges" WHEN NOT (length(NEW."menu_token_hash") = 64 AND NEW."menu_token_hash" NOT GLOB '*[^0-9a-f]*') BEGIN SELECT RAISE(ABORT, 'constraint failed: qr_guest_otp_challenges_menu_token_hash_check'); END;
CREATE TRIGGER IF NOT EXISTS "d1_check_qr_guest_otp_challenges_menu_token_hash_check_update" BEFORE UPDATE ON "qr_guest_otp_challenges" WHEN NOT (length(NEW."menu_token_hash") = 64 AND NEW."menu_token_hash" NOT GLOB '*[^0-9a-f]*') BEGIN SELECT RAISE(ABORT, 'constraint failed: qr_guest_otp_challenges_menu_token_hash_check'); END;
CREATE TRIGGER IF NOT EXISTS "d1_check_qr_guest_otp_challenges_phone_check_insert" BEFORE INSERT ON "qr_guest_otp_challenges" WHEN NOT (length(NEW."phone") = 10 AND NEW."phone" NOT GLOB '*[^0-9]*') BEGIN SELECT RAISE(ABORT, 'constraint failed: qr_guest_otp_challenges_phone_check'); END;
CREATE TRIGGER IF NOT EXISTS "d1_check_qr_guest_otp_challenges_phone_check_update" BEFORE UPDATE ON "qr_guest_otp_challenges" WHEN NOT (length(NEW."phone") = 10 AND NEW."phone" NOT GLOB '*[^0-9]*') BEGIN SELECT RAISE(ABORT, 'constraint failed: qr_guest_otp_challenges_phone_check'); END;
CREATE TRIGGER IF NOT EXISTS "d1_check_qr_guest_sessions_menu_token_hash_check_insert" BEFORE INSERT ON "qr_guest_sessions" WHEN NOT (length(NEW."menu_token_hash") = 64 AND NEW."menu_token_hash" NOT GLOB '*[^0-9a-f]*') BEGIN SELECT RAISE(ABORT, 'constraint failed: qr_guest_sessions_menu_token_hash_check'); END;
CREATE TRIGGER IF NOT EXISTS "d1_check_qr_guest_sessions_menu_token_hash_check_update" BEFORE UPDATE ON "qr_guest_sessions" WHEN NOT (length(NEW."menu_token_hash") = 64 AND NEW."menu_token_hash" NOT GLOB '*[^0-9a-f]*') BEGIN SELECT RAISE(ABORT, 'constraint failed: qr_guest_sessions_menu_token_hash_check'); END;
CREATE TRIGGER IF NOT EXISTS "d1_check_qr_guest_sessions_phone_check_insert" BEFORE INSERT ON "qr_guest_sessions" WHEN NOT (length(NEW."phone") = 10 AND NEW."phone" NOT GLOB '*[^0-9]*') BEGIN SELECT RAISE(ABORT, 'constraint failed: qr_guest_sessions_phone_check'); END;
CREATE TRIGGER IF NOT EXISTS "d1_check_qr_guest_sessions_phone_check_update" BEFORE UPDATE ON "qr_guest_sessions" WHEN NOT (length(NEW."phone") = 10 AND NEW."phone" NOT GLOB '*[^0-9]*') BEGIN SELECT RAISE(ABORT, 'constraint failed: qr_guest_sessions_phone_check'); END;
CREATE TRIGGER IF NOT EXISTS "d1_check_qr_guest_sessions_session_token_hash_check_insert" BEFORE INSERT ON "qr_guest_sessions" WHEN NOT (length(NEW."session_token_hash") = 64 AND NEW."session_token_hash" NOT GLOB '*[^0-9a-f]*') BEGIN SELECT RAISE(ABORT, 'constraint failed: qr_guest_sessions_session_token_hash_check'); END;
CREATE TRIGGER IF NOT EXISTS "d1_check_qr_guest_sessions_session_token_hash_check_update" BEFORE UPDATE ON "qr_guest_sessions" WHEN NOT (length(NEW."session_token_hash") = 64 AND NEW."session_token_hash" NOT GLOB '*[^0-9a-f]*') BEGIN SELECT RAISE(ABORT, 'constraint failed: qr_guest_sessions_session_token_hash_check'); END;
CREATE TRIGGER IF NOT EXISTS "d1_check_qr_service_requests_request_type_check_insert" BEFORE INSERT ON "qr_service_requests" WHEN NOT (NEW."request_type" IN ('clean_table', 'call_waiter')) BEGIN SELECT RAISE(ABORT, 'constraint failed: qr_service_requests_request_type_check'); END;
CREATE TRIGGER IF NOT EXISTS "d1_check_qr_service_requests_request_type_check_update" BEFORE UPDATE ON "qr_service_requests" WHEN NOT (NEW."request_type" IN ('clean_table', 'call_waiter')) BEGIN SELECT RAISE(ABORT, 'constraint failed: qr_service_requests_request_type_check'); END;
